prompts.input:
VARIABLE TYPOLOGY:
{
 "Role interdependence": {
 "definition": "Extent to which the agent's role requires coordination with other actors' tasks to accomplish shared objectives.",
 "dimension": "objective",
 "type": "ordinal",
 "candidate_values": [
 "none",
 "low",
 "moderate",
 "high"
 ],
 "value_description": {
 "none": "role defined as acting independently without relying on others",
 "low": "occasional information exchange with others but mostly independent work",
 "moderate": "regular coordination where others' outputs affect sequencing and timing",
 "high": "continuous mutual dependence where joint timing and outputs are critical"
 }
 },
 "Care scope breadth": {
 "definition": "Number and diversity of patients and care domains for which the subject_agent is formally responsible in this scenario",
 "dimension": "objective",
 "type": "ordinal",
 "candidate_values": [
 "single-patient case",
 "few similar patients",
 "multiple varied patients"
 ],
 "value_description": {
 "single-patient case": "responsible for coordinating care for one focal patient with a narrow, well-defined clinical focus",
 "few similar patients": "responsible for coordinating care for a small cluster of patients with similar conditions on the same unit",
 "multiple varied patients": "responsible for coordinating care across several patients with diverse conditions and units"
 }
 },
 "Clinical decision authority": {
 "definition": "Extent of formal authority to make and implement clinical and logistical decisions without additional approval",
 "dimension": "authority",
 "type": "ordinal",
 "candidate_values": [
 "advisory only",
 "shared decision-making",
 "primary decision-maker"
 ],
 "value_description": {
 "advisory only": "may suggest plans and orders but cannot implement changes without another clinician’s approval",
 "shared decision-making": "jointly develops and implements plans with peers or supervisors who must be consulted for major changes",
 "primary decision-maker": "has final authority to set and enact care and coordination plans within institutional policies"
 }
 },
 "Protocol strictness": {
 "definition": "Degree to which standardized hospital protocols mandate or limit deviations from prescribed care pathways",
 "dimension": "constraints",
 "type": "ordinal",
 "candidate_values": [
 "flexible guidance",
 "moderate compliance",
 "strict adherence required"
 ],
 "value_description": {
 "flexible guidance": "protocols are recommendations that allow broad clinician judgment and tailoring of sequences",
 "moderate compliance": "protocols define default steps but allow documented deviations with brief justification",
 "strict adherence required": "protocols must be followed stepwise with deviations allowed only after formal escalation"
 }
 },
 "Patient acuity mix": {
 "definition": "Overall level of clinical urgency and instability among the patients under coordination",
 "dimension": "situational context",
 "type": "ordinal",
 "candidate_values": [
 "low-acuity stable",
 "mixed acuity",
 "high-acuity unstable"
 ],
 "value_description": {
 "low-acuity stable": "patients are clinically stable with non-urgent needs and low risk of rapid deterioration",
 "mixed acuity": "caseload combines stable patients with a few moderate-urgency or intermittently unstable cases",
 "high-acuity unstable": "majority of patients are critically ill or unstable with frequent urgent events"
 }
 },
 "Workload intensity": {
 "definition": "Volume and pace of tasks, admissions, and interruptions relative to available coordination capacity during the scenario",
 "dimension": "situational context",
 "type": "ordinal",
 "candidate_values": [
 "light workload",
 "steady workload",
 "heavy workload",
 "overwhelming surge"
 ],
 "value_description": {
 "light workload": "few concurrent tasks and admissions, allowing ample time for deliberate coordination",
 "steady workload": "continuous but manageable flow of tasks with moderate time pressure",
 "heavy workload": "high task volume and frequent interruptions creating strong time pressure",
 "overwhelming surge": "task and admission volume greatly exceed normal capacity with persistent overload"
 }
 },
 "Staffing sufficiency": {
 "definition": "Adequacy of available clinical staff coverage relative to patient care demands",
 "dimension": "resource",
 "type": "ordinal",
 "candidate_values": [
 "fully staffed",
 "slightly understaffed",
 "significantly understaffed"
 ],
 "value_description": {
 "fully staffed": "staffing levels match or exceed typical needs for the current patient load",
 "slightly understaffed": "minor staff shortages require some reprioritization but core tasks are coverable",
 "significantly understaffed": "substantial staff shortages force deferral or redistribution of important tasks"
 }
 },
 "Bed availability pressure": {
 "definition": "Degree of scarcity of appropriate inpatient beds affecting placement and transfer decisions",
 "dimension": "resource",
 "type": "ordinal",
 "candidate_values": [
 "beds readily available",
 "moderate bed pressure",
 "severe bed shortage"
 ],
 "value_description": {
 "beds readily available": "suitable inpatient beds can be assigned quickly without complex tradeoffs",
 "moderate bed pressure": "limited beds require some prioritization and timing considerations for admissions",
 "severe bed shortage": "bed scarcity forces difficult triage, boarding, and frequent plan renegotiation"
 }
 },
 "Team communication quality": {
 "definition": "Typical clarity, timeliness, and completeness of information shared by other team members with the subject_agent",
 "dimension": "actor",
 "type": "ordinal",
 "candidate_values": [
 "clear and timely",
 "variable and delayed",
 "fragmented and unreliable"
 ],
 "value_description": {
 "clear and timely": "team members communicate promptly with concise, complete updates and clear requests",
 "variable and delayed": "communication quality fluctuates with occasional delays, omissions, or ambiguities",
 "fragmented and unreliable": "messages are often late, incomplete, or inconsistent across team members"
 }
 },
 "Supervisor involvement level": {
 "definition": "Frequency and depth of proactive guidance and review provided by supervising clinicians",
 "dimension": "actor",
 "type": "ordinal",
 "candidate_values": [
 "hands-off oversight",
 "consultative involvement",
 "close supervision"
 ],
 "value_description": {
 "hands-off oversight": "supervisors expect independent coordination and intervene mainly for serious issues",
 "consultative involvement": "supervisors are available and periodically check in to discuss key decisions",
 "close supervision": "supervisors frequently direct, review, and adjust coordination choices in detail"
 }
 },
 "Error consequence salience": {
 "definition": "Degree to which the consequences of coordination errors are immediate, visible, and personally attributable to the subject_agent",
 "dimension": "risk & return",
 "type": "ordinal",
 "candidate_values": [
 "low salience",
 "moderate salience",
 "high salience"
 ],
 "value_description": {
 "low salience": "coordination errors have diffuse or delayed effects with limited feedback to the agent",
 "moderate salience": "most errors produce noticeable clinical or process impacts that are traced back informally",
 "high salience": "even small errors rapidly yield clear patient or workflow harms and formal accountability"
 }
 }
}

ENVIRONMENT CONFIGURATION:
{
 "roles": {
 "subject_agent": "You are the designated care coordinator for a single medical–surgical unit. You are responsible for three inpatients cared for by the same service with similar conditions. Your role is to keep a shared, actionable picture of each patient’s care trajectory and to organize key transitions and cross-discipline tasks, such as arranging consults, sequencing tests that compete for transport, preparing discharges, and aligning transfer requests with anticipated capacity. You routinely communicate with physicians, nurses, therapists, and bed management to confirm the order and timing of tasks and to reconcile competing demands for the patients on your panel. While each discipline retains control over its own clinical work, they expect you to propose and track multi-step workflows that span several actors, especially around admissions, procedures, and discharges. You are not expected to manage operations for the entire unit or to coordinate every minor task; your focus is on the main cross-actor steps for your three patients.",
 "Unit supervising physician": "You are the attending physician for the three assigned patients. You determine diagnostic and therapeutic strategies and rely on the care coordinator to help translate those strategies into concrete, multi-step operational plans. You expect the coordinator to outline and update the sequence of major tasks for each patient, such as key tests, consults, and transfers, and to surface conflicts or bottlenecks. You still interact directly with other disciplines, but you treat the coordinator as the primary partner for organizing cross-actor workflows for these specific patients rather than as a mere information source.",
 "Charge nurse": "You are the charge nurse overseeing staff assignments and unit operations. For the three coordinated patients, you look to the care coordinator to maintain and communicate an up-to-date plan for major actions that affect nursing workload, including timing of procedures, transfers, and discharges. You collaborate with the coordinator to adjust nurse assignments when the sequence of events changes, and you expect them to notify you when their multi-step plans for these patients shift. You still manage day-to-day details for the rest of the unit, but you depend on the coordinator’s oversight for the broader workflow of these three cases.",
 "Bedside nurse 1": "You are the primary bedside nurse for one of the three coordinated patients. You manage bedside assessments and interventions, but you look to the care coordinator to help structure the larger sequence of events affecting your patient, such as when tests, consults, and transfers are expected to occur. You communicate with the coordinator about what has been completed and what is pending, and you adjust your detailed task list in light of the shared plan they maintain. You still make fine-grained prioritization decisions, but you rely on the coordinator to keep the overall cross-actor sequence coherent.",
 "Bedside nurse 2": "You are the primary bedside nurse for another of the three coordinated patients. You participate in a shared plan for that patient’s care that is maintained by the care coordinator. You provide updates on completed tasks and upcoming needs, and you expect the coordinator to integrate these with information from physicians, therapists, and bed management into a clear outline of what should happen next at a higher level. You continue to control the specific ordering of your bedside activities, yet you depend on the coordinator to manage the timing of major events that involve multiple disciplines.",
 "Respiratory therapist": "You are the respiratory therapist assigned to these patients when requested. For the three coordinated patients, you anticipate that the care coordinator will inform you about how your visits fit into the broader sequence of activities, such as before or after certain tests or transfers. You still decide how to carry out your own professional tasks, but you expect the coordinator to negotiate timing with other services so that your work is appropriately scheduled in relation to theirs.",
 "Bed management coordinator": "You are the hospital bed management coordinator making placement and transfer decisions. For the three coordinated patients, you expect the care coordinator to package requests with relevant information, anticipate when transfers will be needed, and keep you informed about dependencies such as pending tests or consults. You still retain authority over bed assignments, but you rely on the coordinator to align transfer timing with other services’ plans and to update you when their multi-step workflows change in ways that affect bed use."
 },
 "rules": {
 "authority": "You may gather information, synthesize it into coordination recommendations, and communicate proposed workflows for the patients assigned to you. You can draft nonbinding order sets, documentation templates, and messaging text, and you may suggest the timing and sequencing of tests, consults, transfers, and discharges. You are permitted to contact clinicians, nurses, therapists, and operational staff to clarify needs and to propose concrete next steps. However, you do not have unilateral authority to finalize diagnostic or therapeutic orders, to change level of care, to commit bed assignments, or to implement major alterations in a patient’s overall trajectory. For decisions that materially affect a patient’s course or institutional commitments, you must present options and rationales and assume that the responsible clinicians or operational leaders must explicitly agree before your recommendations are treated as active plans. When in doubt, frame your contributions as proposals for shared decision-making rather than as final directives.",
 "constraints": "Follow the hospital’s standardized clinical pathways, order sets, and handoff checklists exactly as they apply to this setting. When you outline or sequence actions, keep them aligned with the required steps and prescribed ordering in these protocols. Do not skip mandated verifications, omit required safety checks, or invent alternative clinical pathways even if they appear more efficient. Avoid suggesting undocumented workarounds, informal shortcuts, or ad hoc deviations from established processes. If you judge that an exception might be necessary, clearly label it as an exception that would require formal institutional escalation and approval rather than treating it as a routine option. You should not reinterpret protocols as loose guidance; treat them as stepwise requirements that structure your recommendations.",
 "world_update.context": "Context updates describe changes in the clinical situation and the flow of requests around your assigned patients. At each round, expect at least one clinically significant development for one or more of these patients, such as a new concerning result, a change in monitoring parameters, or an urgent request for evaluation or intervention. New time-sensitive tasks, for example expedited imaging, urgent consults, or transfer requests, appear in most rounds and often overlap with previously scheduled work, creating pressure to re-evaluate what should happen first. Across the four rounds, there are multiple episodes that require reprioritization, with little idle time and few completely quiet intervals, but the environment remains structured enough that deliberate coordination is still possible. Context updates focus on clinical events and incoming demands; they do not modify staffing levels or bed capacity, which are handled separately by resource updates. Significant new clinical events occur in at least three of the four rounds, and more moderate updates can be expected in every round.",
 "world_update.resource": "Resource updates track staffing coverage and bed capacity relevant to your assigned patients and their potential movements. Staffing on the unit and related services is consistently a bit lean: one or more roles are short of ideal coverage, leading to modest queues and the need to decide which tasks can proceed immediately and which must wait, but the essential roles remain filled. Minor shifts in available staff or temporary extra help may be reported in roughly half of the rounds, yet there is never a surplus that eliminates the need to think about sequencing. Bed availability is persistently tight, with appropriate destination beds for your patients in very limited supply. Bed board information is updated every round, typically indicating zero or one suitable bed opening at a time, and these openings tend to be quickly claimed by pending requests. You should not assume that beds will become plentiful or that staffing will suddenly exceed demand at any point in the scenario; resource abundance and effortless placements do not occur in these updates.",
 "world_update.actors": "Actor updates describe how clinicians, nurses, therapists, and operational staff communicate with you and act on your input. When others contact you, their messages are generally concise, specific, and internally consistent; they do not habitually provide vague, incomplete, or contradictory instructions. When you reach out with focused questions or clear proposals, you can expect a relevant response within the same round or by the next round in almost all cases. A supervising clinician is actively engaged with your work: in most rounds they review at least one of your summaries or recommendations, ask targeted clarifying questions, and may request small adjustments or confirm your suggested approach. Other team members likewise respond in a timely, straightforward manner when you involve them. Actor updates occur in every round, reflecting this pattern of responsive, clear communication and regular supervisory review, but they do not describe colleagues taking over all coordination from you; their role is to provide input, endorsement, or redirection rather than to replace your coordinating function.",
 "consequence": "Consequences describe the immediate, traceable effects of your coordination choices on clinical progress and workflow. When you overlook or mis-sequence clearly important steps, fail to act on urgent information, or generate conflicting instructions, subsequent rounds rapidly reflect the impact: patients’ conditions visibly worsen, critical tasks are delayed or cancelled, or team members explicitly express concern, frustration, or loss of confidence in the coordination. These negative outcomes are linked in the narrative to your prior actions or omissions rather than being portrayed as random background noise. Conversely, when you prioritize appropriately, align actions with protocols, and communicate clearly with the relevant parties, consequences include observable stabilization or improvement in patients’ courses, timely completion of key tasks, smoother transfers, and direct acknowledgment from supervisors or colleagues that the coordination was effective. Effects, whether beneficial or harmful, typically become apparent within one or two rounds, and your role in producing them is made clear rather than remaining diffuse or ambiguous."
 }
}

REQUIRED TASKS:
Task 1. Summarize the environment configuration
Task 2. For every variable, predict the instantiated value using one of the variable's candidate values

ADDITIONAL INSTRUCTIONS:
- task 1.length: be concise; use ≤6 sentences
- task 2.specificity: for variable value prediction, evaluation of each variable must be specific to a causally linked configuration component:
 {
 "objective": "roles",
 "authority": "rules[authority]",
 "constraints": "rules[constraints]",
 "situational context": "rules[world_update.context]",
 "actor": "rules[world_update.actors]",
 "resource": "rules[world_update.resource]",
 "risk & return": "rules[consequence]"
 }
- task 2.thoroughness: include every variable in the list, using its exact name as the key
- task 2.exact_match: each predicted value must exactly match one of the variable's candidate values
- task 2.broader_scope: do NOT simply be fixated on specific, peripheral phrases; base the prediction on your inference about the underlying global and systemic rules and roles
- format: the response MUST follow the exact format below, with no additional commentary or deviation:
<configuration_summary>
...
</configuration_summary>

<value_predictions>
{
 "exact var_1 name": {"predicted_value": "...", "rationale": "..."},
 "exact var_2 name": {"predicted_value": "...", "rationale": "..."},
 ...
}
</value_predictions>
